import torch

class A(torch.nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, input):
        return input


class B(torch.nn.Module):
    def __init__(self):
        super().__init__()
        self.submodules = torch.nn.ModuleList()
        for i in range(20):
            self.submodules.append(A())

    def forward(self, input):
        results = [m(input) for m in self.submodules]
        return torch.stack(results).sum()


class TopModule(torch.nn.Module):
    def __init__(self):
        super().__init__()
        self.submodules = torch.nn.ModuleList()
        for i in range(100):
            self.submodules.append(B())

    def forward(self, input):
        results = [m(input) for m in self.submodules]
        return torch.stack(results).sum()
